import { useMemo, useState } from "react";
import {
  color, fontDisplay, fontMono, glass, homeSpace, motion, radius, artShadow, chrome
} from "../../theme";
import {
  biggestClimbers,
  buildMonthlyChart,
  buildMonthlyReveal,
  chartScopeLabel,
  getNumberOnes,
  listChartDays,
  getChartSnapshot,
  monthKey,
  normalizeChartScope,
} from "../../lib/chartHistory";
import { formatMonthLabel } from "../../lib/mixes";
import { CANONICAL_GENRES } from "../../lib/genres";
import { SCENE_CHANNELS } from "../../lib/sceneChannels";
import CoverImage from "../ui/CoverImage";

function MovementTag({ movement, delta }) {
  if (movement === "up") {
    return <span style={{ color: chrome.plate, fontFamily: fontMono, fontSize: 10, fontWeight: 800 }}>↑{delta}</span>;
  }
  if (movement === "down") {
    return <span style={{ color: chrome.hot, fontFamily: fontMono, fontSize: 10, fontWeight: 800 }}>↓{delta}</span>;
  }
  if (movement === "debut" || movement === "new") {
    return <span style={{ color: chrome.bright, fontFamily: fontMono, fontSize: 10, fontWeight: 800 }}>NEW</span>;
  }
  return <span style={{ color: color.faint, fontFamily: fontMono, fontSize: 10, fontWeight: 700 }}>●</span>;
}

function ScopeChip({ active, label, onClick }) {
  return (
    <button
      type="button"
      onClick={onClick}
      style={{
        flexShrink: 0,
        padding: "8px 12px",
        borderRadius: 999,
        border: `1px solid ${active ? color.ink : glass.border}`,
        background: active ? color.ink : glass.fillStrong,
        color: active ? color.onDark : color.body,
        fontFamily: fontMono,
        fontSize: 10,
        fontWeight: 800,
        letterSpacing: 0.8,
        textTransform: "uppercase",
        cursor: "pointer",
      }}
    >
      {label}
    </button>
  );
}

/**
 * Monthly charts — overall or split by channel / genre, plus archive tabs.
 */
export default function ChartHistoryPanel({
  countdown = [],
  tracks = [],
  onPlayTrack = null,
  onTuneMonthly = null,
}) {
  const [tab, setTab] = useState("month"); // month | climbers | ones | archive
  const [scopeMode, setScopeMode] = useState("overall"); // overall | channel | genre
  const [channelId, setChannelId] = useState(SCENE_CHANNELS[0]?.id || null);
  const [genre, setGenre] = useState(CANONICAL_GENRES[0] || "Electronic");
  const [archiveDay, setArchiveDay] = useState(null);

  const scope = useMemo(
    () => normalizeChartScope({
      mode: scopeMode,
      channelId,
      genre,
    }),
    [scopeMode, channelId, genre]
  );

  const month = monthKey();
  const monthLabel = formatMonthLabel(month);

  const monthlyLive = useMemo(
    () => buildMonthlyChart(tracks, { limit: 20, scope }),
    [tracks, scope]
  );
  const monthlyReveal = useMemo(
    () => buildMonthlyReveal(20, { scope, tracks }),
    [tracks, scope, countdown.length]
  );
  // Prefer live heat for the month board; fall back to peak-from-days if empty
  const monthlyEntries = monthlyLive.length
    ? monthlyLive.map((c) => ({
        rank: c.rank,
        id: c.track.id,
        title: c.track.title,
        artist: c.track.artist,
        albumCover: c.track.albumCover,
        movement: "same",
        delta: 0,
      }))
    : monthlyReveal.map((e) => ({
        rank: e.monthRank,
        id: e.id,
        title: e.title,
        artist: e.artist,
        albumCover: e.albumCover,
        movement: "same",
        delta: 0,
        meta: e.peakDay,
      }));

  const climbers = useMemo(() => biggestClimbers(countdown, 5), [countdown]);
  const ones = useMemo(() => getNumberOnes(10), [countdown]);
  const days = useMemo(() => listChartDays(10), [countdown]);

  const archive = archiveDay ? getChartSnapshot(archiveDay) : null;

  if (!tracks.length && !countdown.length && !ones.length) return null;

  const playEntry = (entry, list) => {
    if (!entry?.id || !onPlayTrack) return;
    const track = tracks.find((t) => t.id === entry.id) || {
      id: entry.id,
      title: entry.title,
      artist: entry.artist,
      albumCover: entry.albumCover,
    };
    const pool = list
      .map((e) => tracks.find((t) => t.id === e.id))
      .filter(Boolean);
    onPlayTrack(track, pool.length ? pool : [track]);
  };

  const scopeTitle = chartScopeLabel(scope);

  return (
    <section
      aria-label="Monthly charts"
      style={{
        padding: `8px 0 ${homeSpace.sectionPadBottom}px`,
        animation: `rise 0.55s ${motion.ease} 0.05s both`,
      }}
    >
      <div style={{ padding: `0 ${homeSpace.gutter}px 12px` }}>
        <div style={{
          fontFamily: fontMono, fontSize: 10, fontWeight: 800,
          letterSpacing: 1.5, textTransform: "uppercase", color: chrome.steel,
          marginBottom: 4,
        }}>
          Monthly chart · {monthLabel}
        </div>
        <h3 style={{
          margin: 0,
          fontFamily: fontDisplay,
          fontSize: "clamp(20px, 4vw, 26px)",
          fontWeight: 750,
          letterSpacing: -0.4,
          color: color.ink,
        }}>
          {scopeTitle}
        </h3>
      </div>

      <div style={{
        display: "flex", gap: 6, padding: `0 ${homeSpace.gutter}px 10px`,
        overflowX: "auto",
      }} className="hide-scroll">
        {[
          { id: "overall", label: "Overall" },
          { id: "channel", label: "By channel" },
          { id: "genre", label: "By genre" },
        ].map((t) => (
          <ScopeChip
            key={t.id}
            active={scopeMode === t.id}
            label={t.label}
            onClick={() => setScopeMode(t.id)}
          />
        ))}
      </div>

      {scopeMode === "channel" && (
        <div style={{
          display: "flex", gap: 6, padding: `0 ${homeSpace.gutter}px 10px`,
          overflowX: "auto",
        }} className="hide-scroll">
          {SCENE_CHANNELS.map((ch) => (
            <ScopeChip
              key={ch.id}
              active={channelId === ch.id}
              label={`CH-${String(ch.num).padStart(2, "0")} ${ch.shortTitle || ch.title}`}
              onClick={() => setChannelId(ch.id)}
            />
          ))}
        </div>
      )}

      {scopeMode === "genre" && (
        <div style={{
          display: "flex", gap: 6, padding: `0 ${homeSpace.gutter}px 10px`,
          overflowX: "auto",
        }} className="hide-scroll">
          {CANONICAL_GENRES.map((g) => (
            <ScopeChip
              key={g}
              active={genre === g}
              label={g}
              onClick={() => setGenre(g)}
            />
          ))}
        </div>
      )}

      <div style={{
        display: "flex", gap: 6, padding: `0 ${homeSpace.gutter}px 12px`,
        overflowX: "auto",
      }} className="hide-scroll">
        {[
          { id: "month", label: "This month" },
          { id: "climbers", label: "Climbers" },
          { id: "ones", label: "#1s" },
          { id: "archive", label: "Past days" },
        ].map((t) => (
          <button
            key={t.id}
            type="button"
            onClick={() => setTab(t.id)}
            style={{
              flexShrink: 0,
              padding: "8px 12px",
              borderRadius: 999,
              border: `1px solid ${tab === t.id ? color.ink : glass.border}`,
              background: tab === t.id ? color.ink : glass.fillStrong,
              color: tab === t.id ? color.onDark : color.body,
              fontFamily: fontMono,
              fontSize: 10,
              fontWeight: 800,
              letterSpacing: 0.8,
              textTransform: "uppercase",
              cursor: "pointer",
            }}
          >
            {t.label}
          </button>
        ))}
      </div>

      <div style={{ padding: `0 ${homeSpace.gutter}px` }}>
        {tab === "month" && (
          <>
            {onTuneMonthly && monthlyEntries.length > 0 && (
              <button
                type="button"
                onClick={() => onTuneMonthly(scope)}
                style={{
                  width: "100%",
                  marginBottom: 10,
                  padding: "12px 14px",
                  borderRadius: radius.sm,
                  border: "1px solid rgba(197,202,211,0.4)",
                  background: `linear-gradient(165deg, ${chrome.bright} 0%, ${chrome.hot} 120%)`,
                  color: "#16181E",
                  fontFamily: fontMono,
                  fontSize: 11,
                  fontWeight: 800,
                  letterSpacing: 1.1,
                  textTransform: "uppercase",
                  cursor: "pointer",
                }}
              >
                Play monthly chart
              </button>
            )}
            {monthlyEntries.length ? (
              <ChartList
                entries={monthlyEntries}
                onPlay={(e, list) => playEntry(e, list)}
              />
            ) : (
              <Empty note="No cuts in this scope yet — play and request to fill the monthly chart." />
            )}
          </>
        )}

        {tab === "climbers" && (
          climbers.length ? (
            <ChartList
              entries={climbers.map((c) => ({
                rank: c.rank,
                id: c.track.id,
                title: c.track.title,
                artist: c.track.artist,
                albumCover: c.track.albumCover,
                movement: c.movement,
                delta: c.delta,
              }))}
              onPlay={(e, list) => playEntry(e, list)}
            />
          ) : (
            <Empty note="Play and request across two days to unlock climbers." />
          )
        )}

        {tab === "ones" && (
          ones.length ? (
            <ChartList
              entries={ones.map((e, i) => ({
                rank: i + 1,
                id: e.id,
                title: e.title,
                artist: e.artist,
                albumCover: e.albumCover,
                movement: "same",
                meta: e.dayKey,
              }))}
              onPlay={(e, list) => playEntry(e, list)}
            />
          ) : (
            <Empty note="Number-ones appear as daily charts are captured." />
          )
        )}

        {tab === "archive" && (
          <>
            <div style={{ display: "flex", gap: 6, overflowX: "auto", marginBottom: 10 }} className="hide-scroll">
              {days.map((d) => (
                <button
                  key={d}
                  type="button"
                  onClick={() => setArchiveDay(d)}
                  style={{
                    flexShrink: 0,
                    padding: "8px 10px",
                    borderRadius: radius.sm,
                    border: `1px solid ${archiveDay === d ? color.ink : glass.border}`,
                    background: archiveDay === d ? color.surfaceRaised : glass.fillStrong,
                    fontFamily: fontMono,
                    fontSize: 10,
                    fontWeight: 700,
                    cursor: "pointer",
                    color: color.ink,
                  }}
                >
                  {d.slice(5)}
                </button>
              ))}
            </div>
            {archive ? (
              <ChartList
                entries={archive.entries.map((e) => ({
                  rank: e.rank,
                  id: e.id,
                  title: e.title,
                  artist: e.artist,
                  albumCover: e.albumCover,
                  movement: "same",
                }))}
                onPlay={(e, list) => playEntry(e, list)}
              />
            ) : (
              <Empty note={days.length ? "Pick a day." : "Archive builds as you listen."} />
            )}
          </>
        )}
      </div>
    </section>
  );
}

function Empty({ note }) {
  return (
    <div className="glass-surface" style={{ padding: 16, borderRadius: radius.md, color: color.muted, fontSize: 13 }}>
      {note}
    </div>
  );
}

function ChartList({ entries, onPlay }) {
  return (
    <ol style={{ listStyle: "none", margin: 0, padding: 0, display: "flex", flexDirection: "column", gap: 6 }}>
      {entries.map((e) => (
        <li key={`${e.id}-${e.rank}`}>
          <button
            type="button"
            onClick={() => onPlay?.(e, entries)}
            style={{
              width: "100%",
              display: "flex",
              alignItems: "center",
              gap: 10,
              padding: "10px 12px",
              borderRadius: radius.md,
              border: `1px solid ${glass.borderSoft}`,
              background: "rgba(32,36,43,0.65)",
              boxShadow: `inset 0 1px 0 ${glass.highlight}`,
              cursor: "pointer",
              textAlign: "left",
            }}
          >
            <div style={{
              width: 28, fontFamily: fontMono, fontWeight: 800, fontSize: 14,
              color: e.rank <= 3 ? chrome.bright : color.ink, textAlign: "center",
            }}>
              {e.rank}
            </div>
            <div style={{
              width: 40, height: 40, borderRadius: 5, overflow: "hidden", flexShrink: 0,
              background: color.surfaceRaised, boxShadow: artShadow.quiet,
            }}>
              <CoverImage src={e.albumCover} width={40} height={40} alt="" />
            </div>
            <div style={{ minWidth: 0, flex: 1 }}>
              <div style={{ fontSize: 13, fontWeight: 650, color: color.ink, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                {e.title}
              </div>
              <div style={{ fontSize: 11, color: color.muted, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                {e.artist}{e.meta ? ` · ${e.meta}` : ""}
              </div>
            </div>
            <MovementTag movement={e.movement} delta={e.delta} />
          </button>
        </li>
      ))}
    </ol>
  );
}
